import { useSelector } from 'react-redux';
import { selectDarkMode } from '../store/slices/uiSlice';

/**
 * Returns a `t(darkClass, lightClass)` helper and the raw darkMode boolean.
 * Usage:  const { t, dark } = useTheme();
 *         className={t('text-white', 'text-black')}
 */
export function useTheme() {
  const dark = useSelector(selectDarkMode);
  const t = (darkClass, lightClass) => (dark ? darkClass : lightClass);

  // Convenient grouped tokens
  const tokens = {
    bg:      t('bg-[#0f0f13]',  'bg-[#f8f7ff]'),
    sidebar: t('bg-[#13131a]',  'bg-[#f0f0fa]'),
    chat:    t('bg-[#0f0f13]',  'bg-white'),
    card:    t('bg-[#1a1a24]',  'bg-white'),
    input:   t('bg-[#1a1a26]',  'bg-[#f4f4fc]'),
    border:  t('border-[#22222e]', 'border-[#e0e0f0]'),
    text:    t('text-[#e8e8f0]', 'text-[#1a1a2e]'),
    muted:   'text-[#7878a0]',
    hover:   t('hover:bg-[#1c1c28]', 'hover:bg-[#eeeeff]'),
    msgBot:  t('bg-[#1e1e2e]',  'bg-[#f3f3ff]'),
    // raw hex values (for inline styles)
    textHex:   t('#e8e8f0', '#1a1a2e'),
    mutedHex:  '#7878a0',
    borderHex: t('#22222e', '#e0e0f0'),
    inputHex:  t('#1a1a26', '#f4f4fc'),
    hoverHex:  t('#1c1c28', '#eeeeff'),
    bgHex:     t('#0f0f13', '#f8f7ff'),
    sidebarHex:t('#13131a', '#f0f0fa'),
    chatHex:   t('#0f0f13', '#ffffff'),
    cardHex:   t('#1a1a24', '#ffffff'),
    msgBotHex: t('#1e1e2e', '#f3f3ff'),
  };

  return { dark, t, ...tokens };
}
